    'faq' => [
        ['q' => 'Un site ou une application doit-il être déclaré à la commission de protection des données de Djibouti ?', 'r' => 'En règle générale, oui. L\'article 66 du Code du numérique soumet les traitements automatisés de données personnelles à une déclaration préalable, avec un récépissé qui autorise le démarrage. Des déclarations simplifiées existent pour les traitements courants, et certains cas, comme les données génétiques, exigent une autorisation. La mise en service effective de la commission est à confirmer auprès des autorités.'],
        ['q' => 'Peut-on encaisser avec D-Money sur un site marchand ?', 'r' => 'Oui. Djibouti Telecom a lancé en décembre 2023 une offre de paiement en ligne pour les entreprises de commerce électronique et les institutions publiques, adossée à plusieurs banques. L\'intégration se prépare avec le prestataire, qui remet les accès techniques une fois le contrat marchand signé. Richard SALANON écrit ensuite le module et le rapproche des commandes.'],
        ['q' => 'Le site doit-il être en arabe et en français ?', 'r' => 'Ce n\'est pas une obligation légale relevée dans le Code du numérique, mais l\'arabe et le français sont les deux langues officielles du pays, selon sa constitution. Un site bilingue touche plus de clients et rassure. La version arabe demande une mise en page de droite à gauche et des textes relus par un locuteur.'],
        ['q' => 'Peut-on héberger les données d\'une entreprise de Djibouti en Europe ?', 'r' => 'C\'est possible, à condition de documenter le transfert. L\'article 99 du Code du numérique n\'autorise l\'envoi de données vers un pays tiers que si le niveau de protection y est équivalent, et l\'article 102 prévoit des exceptions, dont le consentement exprès. Le choix de l\'hébergeur se discute donc au cadrage, avec la direction de l\'entreprise.'],
        ['q' => 'Quelle TVA appliquer sur une facture à Djibouti ?', 'r' => 'Selon l\'édition officielle 2015 du Code général des impôts, le taux normal est de 10 % et la facture mentionne le NIF du vendeur et du client, le taux et le montant de la TVA. Les textes et guides publiés ne donnent pas le même seuil d\'assujettissement : ce seuil, et tout changement postérieur à 2015, se confirment auprès de la Direction des impôts avant de paramétrer la facturation.'],
        ['q' => 'Djibouti fait-il partie de l\'OHADA ?', 'r' => 'Non. L\'OHADA compte dix-sept États, dont la liste est publiée sur ohada.com, et Djibouti n\'y figure pas. Les entreprises djiboutiennes n\'appliquent donc pas le SYSCOHADA : un logiciel comme Odoo ou Dolibarr se paramètre avec le plan de comptes que leur cabinet comptable utilise.'],
        ['q' => 'Quelle est la différence d\'heure entre Djibouti et Cotonou ?', 'r' => 'Djibouti est en UTC+3 toute l\'année, le Bénin en UTC+1 : 8 h à Cotonou correspondent à 10 h à Djibouti. Les visioconférences se calent sur ce décalage de deux heures, et le travail avance ensuite de façon asynchrone, avec un compte rendu écrit après chaque séance.'],
        ['q' => 'Dans quelle devise le devis est-il établi, et comment le régler ?', 'r' => 'En euros. Il se règle par virement, par carte bancaire ou par PayPal. Le franc Djibouti étant rattaché au dollar américain à 177,721 francs pour 1 dollar, selon la Banque centrale de Djibouti, la contrevaleur en francs Djibouti varie avec le cours de l\'euro face au dollar.'],
        ['q' => 'Richard intervient-il à Djibouti, sur place ou à distance ?', 'r' => 'Richard SALANON peut accompagner à distance les entreprises à Djibouti : cadrage en visioconférence, développement, livraison et formation. Il est basé à Cotonou, au Bénin. Les références de son portfolio sont présentées sur la page Réalisations.'],
        ['q' => 'Les formations se donnent-elles à distance, et qui peut les financer ?', 'r' => 'Oui, en visioconférence, sur les outils et les documents de l\'entreprise, en français. Pour le financement, l\'Agence nationale pour l\'emploi, la formation et l\'insertion professionnelle est citée par l\'Agence djiboutienne de développement social parmi ses partenaires ; les conditions de prise en charge sont à confirmer auprès d\'elle.'],
    ],

